        .init(id: "unsigned-consultation-on-request", code: "invalid",
              sentence: "A signed consultation is required before requesting medicine.",
              fills: []),
        .init(id: "quantity-out-of-bounds", code: "invalid",
              sentence: "Quantity must be a whole number between {min} and {max}.",
              fills: ["min", "max"]),
        .init(id: "already-dispensed", code: "invalid",
              sentence: "This request has already been dispensed.",
              fills: []),
        .init(id: "checks-outstanding", code: "invalid",
              sentence: "Verify the original prescription and reconcile the allergy record first.",
              fills: []),
        .init(id: "batch-unusable", code: "invalid",
              sentence: "Choose a matching, unexpired stock batch.",
              fills: []),
        .init(id: "batch-short", code: "invalid",
              sentence: "There is not enough stock in this batch.",
              fills: []),
        .init(id: "recipient-unchecked", code: "invalid",
              sentence: "Verify the prescription and recipient before release.",
              fills: []),
        .init(id: "batch-short-at-release", code: "invalid",
              sentence: "Stock is insufficient or expired. Verify a new batch.",
              fills: []),
        .init(id: "no-connection", code: "invalid",
              sentence: "No wearable connection exists for this patient.",
              fills: []),
        .init(id: "connection-not-explicit", code: "invalid",
              sentence: "Connection and consent must be explicit.",
              fills: []),
        .init(id: "wearable-consent-required", code: "invalid",
              sentence: "Explicit wearable sharing consent is required.",
              fills: []),
        .init(id: "sharing-paused", code: "invalid",
              sentence: "Wearable sharing is paused or consent has been withdrawn.",
              fills: []),
        .init(id: "sample-wrong-patient", code: "invalid",
              sentence: "The sample belongs to a different patient.",
              fills: []),
        .init(id: "sample-not-simulated", code: "invalid",
              sentence: "The sandbox accepts labelled simulator samples only.",
              fills: []),
        .init(id: "sample-unidentified", code: "invalid",
              sentence: "Sample and device identifiers are required.",
              fills: []),
        .init(id: "sample-value-invalid", code: "invalid",
              sentence: "Sample type, unit or numeric value is invalid.",
              fills: []),
        .init(id: "sample-quality-required", code: "invalid",
              sentence: "Sample quality is required.",
              fills: []),
        .init(id: "sample-time-invalid", code: "invalid",
              sentence: "Sample time is invalid or in the future.",
              fills: []),
